ALTER TABLE public.aperture_industries ADD COLUMN IF NOT EXISTS group_slug text;

UPDATE public.aperture_industries SET group_slug = CASE group_label
  WHEN 'Food & Hospitality' THEN 'food-hospitality'
  WHEN 'Beauty & Wellness' THEN 'beauty-wellness'
  WHEN 'Retail & E-Commerce' THEN 'retail-ecommerce'
  WHEN 'Professional Services & Agencies' THEN 'professional-services'
  WHEN 'Coaching, Consulting & Therapy' THEN 'coaching-consulting-therapy'
  WHEN 'Education & Tutoring' THEN 'education-tutoring'
  WHEN 'Real Estate' THEN 'real-estate'
  WHEN 'General Contracting & Renovation' THEN 'general-contracting'
  WHEN 'Outdoor & Recurring Trade Services' THEN 'outdoor-trade-services'
  WHEN 'Medical & Dental Practices' THEN 'medical-dental'
  WHEN 'Fitness, Training & Movement' THEN 'fitness-training'
  ELSE NULL
END;

ALTER TABLE public.aperture_buckets
  ADD COLUMN IF NOT EXISTS kind text NOT NULL DEFAULT 'default',
  ADD COLUMN IF NOT EXISTS industry_group_slug text,
  ADD COLUMN IF NOT EXISTS metadata jsonb NOT NULL DEFAULT '{}'::jsonb;

CREATE INDEX IF NOT EXISTS aperture_buckets_kind_group_idx
  ON public.aperture_buckets (kind, industry_group_slug);

CREATE UNIQUE INDEX IF NOT EXISTS aperture_bucket_questions_slug_key_uniq
  ON public.aperture_bucket_questions (bucket_slug, question_key);

ON CONFLICT (slug) DO UPDATE SET title=EXCLUDED.title, kind=EXCLUDED.kind, industry_group_slug=EXCLUDED.industry_group_slug, target_count=EXCLUDED.target_count, metadata=EXCLUDED.metadata, is_active=true;

ON CONFLICT DO NOTHING;